import {RitControl} from '/rit-control.mjs';
import {financialChart,financialPeriodLabel} from '/financial-chart.mjs';
import {fleetIllustration} from '/fleet-scenes.mjs';
import {renderRitChart} from '/rit-chart.mjs';
import {installChartTooltip} from '/chart-tooltip.mjs';
import {reportTrend,renderReportTrend} from '/report-trend.mjs';
import {revenueDistribution} from '/visual-model.mjs';
import {mountOperationsMap} from '/map-controller.mjs';
import {parseMoney} from '/sheet-model.mjs';
import {financialLabel} from '/labels.mjs';
import {SpreadsheetEditor} from '/sheet-editor.mjs';
import {importInitialData,IMPORT_KEY,repairSeptemberYear,repairCoordinationCategory} from '/bootstrap.mjs';
import {plates,incomeCategories,expenseCategories,categoriesFor,categoryLabel,clientKey,clientName,today,monthLabel,monthKey,dateIssue,defaultReportMonth,previousMonth,totals,issues,selectRows,availableMonths,clientSummary,weeklyRows,empty,normalize,validate,monthlyReportKey} from '/domain.mjs';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const hideChartTooltip=installChartTooltip(app);
const paths={dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',clients:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.8',finance:'M3 5h18v15H3zM3 9h18M16 14h2',truck:'M2 5h12v12H2zM14 9h4l4 5v3h-8M5 17a2 2 0 1 0 0 4 2 2 0 0 0 0-4M18 17a2 2 0 1 0 0 4 2 2 0 0 0 0-4',trip:'M4 6h11M12 3l3 3-3 3M20 18H9M12 15l-3 3 3 3',report:'M6 3h12v18H6zM9 8h6M9 12h6M9 16h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3',plus:'M12 5v14M5 12h14',download:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',arrow:'M5 12h14M13 6l6 6-6 6',up:'M7 17L17 7M7 7h10v10',down:'M7 7l10 10M7 17h10V7',warning:'M12 3L2 21h20L12 3zM12 9v5M12 17v1',calendar:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16',check:'M5 12l4 4L19 6',menu:'M4 6h16M4 12h16M4 18h16',print:'M6 8V3h12v5M6 17H3V8h18v9h-3M6 14h12v7H6z',refresh:'M20 7a8 8 0 1 0 1 8M20 3v5h-5',file:'M14 2H5v20h14V7zM14 2v6h5M8 12h7M8 16h7'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.dashboard}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rup=v=>v===null?'Belum diisi':'Rp '+Number(v).toLocaleString('id-ID');
const compact=v=>'Rp '+(Math.abs(v)>=1e6?(v/1e6).toLocaleString('id-ID',{maximumFractionDigits:2})+' jt':Number(v).toLocaleString('id-ID'));
const fmt=d=>d?new Date(d+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}):'Tanpa tanggal';
const options=(values,v)=>values.map(x=>`<option value="${esc(x)}" ${x===v?'selected':''}>${esc(financialLabel(x))}</option>`).join('');
const categoryTitle=c=>financialLabel(categoryLabel(c));
const badge=s=>`<span class="badge ${s==='Pengeluaran'?'tx-expense':s==='Pemasukan'?'tx-income':['Siap jalan','Selesai','Ditinjau'].includes(s)?'green':['Servis','Dalam perjalanan','Draft'].includes(s)?'amber':''}">${esc(financialLabel(s))}</span>`;
let state,status={},page='dashboard',month='all',truck='all',client='all',search='',quality='all',type='all',offset=0,busy=false,reportMonth=today().slice(0,7),formKind='',formId='',reportTruck='all';
const LOCAL_KEY='tanjung-priok-workspace-v1';
const sheetEditor=new SpreadsheetEditor({getState:()=>state,saveState:next=>commit(next),onSaved:()=>{reportMonth=defaultReportMonth(state);},onDirty:dirty=>{const label=document.querySelector('[data-sheet-dirty]');if(label)label.hidden=!dirty;}});
const control=new RitControl({api,getState:()=>state,toast,onNavigate:target=>{page=target.page;month='all';client=target.customer?clientKey(target.customer):'all';truck=target.plate||'all';if(page==='sheets'&&target.plate){sheetEditor.plate=target.plate;sheetEditor.period='all';sheetEditor.selected=null;}search='';quality='all';type='all';offset=0;if(target.transaction){const row=state.transactions.find(t=>t.id===target.transaction);if(row){truck=row.plate;search=row.description;}else toast('Sumber transaksi tidak ada di Accounting browser ini.');}render();window.scrollTo(0,0);}});
const names={control:'Kontrol rit & kasbon',sheets:'Accounting',dashboard:'Ringkasan bisnis',clients:'Klien & Revenue',finance:'Buku transaksi',fleet:'Armada',trips:'Operasional',reports:'Laporan mingguan',monthly:'Laporan bulanan',settings:'Data & cadangan'};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
async function api(action,method='GET',body){const r=await fetch('/api/index?action='+action,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let b;try{b=await r.json();}catch{throw Error('Server belum merespons dengan benar. Coba muat ulang.');}if(!r.ok){if(r.status===401){state=null;modal.close();loginView('Sesi berakhir. Silakan masuk kembali.');}throw Error(b.error||'Permintaan gagal.');}return b;}
function localRead(){repairSeptemberYear(localStorage);repairCoordinationCategory(localStorage);const raw=localStorage.getItem(LOCAL_KEY);if(!raw)return empty();const s=normalize(JSON.parse(raw));validate(s);return s;}
function loginView(message=''){
 control.reset();
 const providerError=new URLSearchParams(location.search).get('login_error');
 app.innerHTML=`<main class="login-shell"><section class="panel login-card"><img src="/brand/logo-mark.png" width="56" height="56" alt=""><span class="login-kicker">PT JAYA BINTANG TERANG</span><h1>Workspace</h1><p>Pencatatan keuangan, kinerja armada, dan laporan manajemen dalam satu workspace.</p>${status.configured&&status.googleLogin?`<button type="button" class="btn google-login" data-action="google-login"><svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path fill="#4285F4" d="M21.6 12.2c0-.7-.1-1.4-.2-2.1H12v4h5.4a4.7 4.7 0 0 1-2 3.1v2.6h3.3c1.9-1.8 2.9-4.3 2.9-7.6Z"/><path fill="#34A853" d="M12 22c2.7 0 5-.9 6.7-2.4l-3.3-2.6c-.9.6-2 .9-3.4.9-2.6 0-4.8-1.8-5.6-4.1H3v2.7A10 10 0 0 0 12 22Z"/><path fill="#FBBC05" d="M6.4 13.8a6 6 0 0 1 0-3.6V7.5H3a10 10 0 0 0 0 9l3.4-2.7Z"/><path fill="#EA4335" d="M12 6.1c1.5 0 2.8.5 3.8 1.5l2.9-2.8A9.6 9.6 0 0 0 12 2a10 10 0 0 0-9 5.5l3.4 2.7A5.9 5.9 0 0 1 12 6.1Z"/></svg>Masuk dengan Google</button><p class="login-help">Gunakan akun Google yang terdaftar untuk mengakses workspace.</p>`:status.configured?`<form id="login-form"><label for="login-email">Alamat email</label><input id="login-email" name="email" type="email" autocomplete="email" maxlength="254" required placeholder="nama@gmail.com"><button class="btn primary" type="submit">Kirim link login</button></form><p>Tanpa password. Buka tautan dari email di browser ini.</p>`:'<p>Login belum diaktifkan. Administrator perlu menyelesaikan konfigurasi akses akun.</p>'}<p id="login-message" role="status">${esc(message||(providerError==='cancelled'?'Proses masuk dibatalkan. Silakan pilih akun kembali.':''))}</p><div class="login-team-note">${icon('check')}Akses terbatas untuk tim internal</div></section></main>`;
}
async function boot(){try{status=await api('status');const loginTest=new URLSearchParams(location.search).get('login')==='google';if((loginTest&&status.googleLogin&&!status.sessionAuthenticated)||!status.authenticated){state=null;loginView();return;}if(status.storage==='browser'){state=localRead();if(status.publicImport&&!localStorage.getItem(IMPORT_KEY))state=importInitialData(localStorage,normalize(await api('initial-data')));}else state=normalize(await api('state'));validate(state);reportMonth=defaultReportMonth(state);render();}catch(e){state=null;app.innerHTML=`<div class="loading"><h2>Datanya belum berhasil dimuat.</h2><p>${esc(e.message)}</p><button class="btn" data-action="reload">Coba lagi</button></div>`;}}
app.addEventListener('submit',async e=>{if(e.target.id!=='login-form')return;e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const result=await api('login','POST',{email:new FormData(e.target).get('email')});$('#login-message').textContent=result.message;}catch(err){$('#login-message').textContent=err.message;}finally{button.disabled=false;}});
async function commit(next){if(busy)throw Error('Penyimpanan sedang berjalan.');next=normalize(next);validate(next);busy=true;try{if(status.storage==='browser'){const session=await api('status');if(!session.authenticated){state=null;loginView('Sesi berakhir. Silakan masuk kembali.');throw Error('Silakan masuk kembali.');}const old=localRead();if(old.revision!==state.revision)throw Error('Data berubah di tab lain. Muat ulang sebelum menyimpan.');const saved={...next,revision:old.revision+1,updatedAt:new Date().toISOString(),audit:[{id:crypto.randomUUID(),at:new Date().toISOString(),action:'Pembaruan data',transactions:next.transactions.length,trips:next.trips.length},...(old.audit||[])].slice(0,100)};try{localStorage.setItem(LOCAL_KEY,JSON.stringify(saved));}catch{throw Error('Penyimpanan browser penuh atau diblokir. Ekspor cadangan sebelum melanjutkan.');}state=saved;}else state=normalize(await api('state','PUT',next));toast('Perubahan tersimpan.');}finally{busy=false;}}
window.addEventListener('storage',e=>{if(e.key===LOCAL_KEY&&status.storage==='browser')toast('Data berubah di tab lain. Muat ulang sebelum menyimpan.');});
const scoped=()=>selectRows(state,{month,plate:truck,client});
const allClients=()=>clientSummary(state.transactions,state.clients);
const cname=key=>clientName(allClients().find(c=>c.key===key)?.name||key);
const clientLogo=(name,extra='')=>{const assets={'sinergi':['sinergi-logo.png','Sinergi'],'giant transporter indonesia':['giant-transporter-logo.png','Giant Transporter Indonesia']};const asset=Object.hasOwn(assets,clientKey(name))?assets[clientKey(name)]:null;return asset?`<img class="client-logo ${extra}" src="/brand/${asset[0]}" alt="${asset[1]}" loading="lazy">`:'';};
const scopeLabel=()=>month==='all'?'Seluruh periode':month==='unassigned'?'Periode gabungan / belum jelas':monthLabel(month);
function filters({operational=false,clients=true}={}){return `<div class="filters"><div class="filter-group">${!operational?`<label class="filter-field"><span>PERIODE</span><select id="month-filter" aria-label="Bulan laporan"><option value="all">Seluruh periode</option>${availableMonths(state).map(m=>`<option value="${m}" ${month===m?'selected':''}>${monthLabel(m)}</option>`).join('')}<option value="unassigned" ${month==='unassigned'?'selected':''}>Periode gabungan / belum jelas</option></select></label>`:''}<label class="filter-field"><span>ARMADA</span><select id="truck-filter" aria-label="Filter armada"><option value="all">Semua armada</option>${options(plates,truck)}</select></label>${clients?`<label class="filter-field"><span>KLIEN</span><select id="client-filter" aria-label="Filter klien"><option value="all">Semua klien</option>${allClients().map(c=>`<option value="${esc(c.key)}" ${client===c.key?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`:''}</div>${clientLogo(client,'client-filter-logo')}<button class="text-btn" data-action="reset">Reset filter</button></div>`;}
function stat(label,value,sub,i='finance',extra=''){return `<article class="stat"><div class="stat-head">${label}<span class="stat-icon">${icon(i)}</span></div><strong class="${extra}">${value}</strong><small>${sub}</small></article>`;}
function financeStats(rs){const t=totals(rs);return `<div class="stats">${stat('Revenue tercatat',compact(t.income),`${rs.filter(t=>t.type==='Pemasukan').length} transaksi revenue`,'up','positive')}${stat('Expenses tercatat',compact(t.expense),`${rs.filter(t=>t.type==='Pengeluaran').length} catatan biaya`,'down','negative')}${stat('Selisih tercatat',compact(t.income-t.expense),'Belum termasuk nominal yang kosong','finance',t.income<t.expense?'negative':'positive')}${stat('Rit tercatat',t.rit.toLocaleString('id-ID')+' rit','Berdasarkan catatan transaksi','truck')}</div>`;}
function dataNotice(rs=state.transactions){const n=rs.filter(issues).length;if(!n)return '';return `<div class="notice">${icon('warning')}<div><strong>${n} catatan perlu diperiksa.</strong> ${rs.filter(t=>!t.date).length} tanpa tanggal · ${rs.filter(t=>t.income===null||t.expense===null).length} nominal kosong · ${rs.filter(t=>t.category==='Perlu cek').length} kategori perlu dicek · ${rs.filter(dateIssue).length} tanggal perlu ditinjau. <button class="text-btn" data-action="review">Tinjau transaksi →</button></div></div>`;}
function emptyBlock(title,sub,action='add-tx',label='Tambah transaksi'){return `<div class="empty"><div class="empty-illustration" aria-hidden="true"><span></span><div class="empty-symbol">${icon(({'add-client':'clients','add-trip':'truck','add-report':'report'})[action]||'file')}</div><i></i><b></b></div><h3>${title}</h3><p>${sub}</p><button class="btn primary" ${page==='dashboard'&&action==='add-tx'?'data-page="sheets"':`data-action="${action}"`}>${icon('plus')}${page==='dashboard'&&action==='add-tx'?'Buka Accounting':label}</button></div>`;}
function incomeChart(rs,{revenueOnly=false,showRit=false}={}){
 if(revenueOnly)rs=rs.filter(t=>t.type==='Pemasukan');
 const {data,summary}=financialChart(rs),rawMax=Math.max(0,...data.flatMap(r=>revenueOnly?[r.income]:[r.income,r.expense])),max=Math.max(1,rawMax);
 return `<section class="panel analytic-chart ${revenueOnly?'revenue-only':''}"><div class="panel-head"><div><h3>${revenueOnly?'Tren Revenue Bulanan':'Revenue & Expenses'}</h3><div class="subtitle">Total sesuai filter</div></div><div class="legend"><span><i></i>Revenue</span>${revenueOnly?'':'<span><i class="orange"></i>Expenses</span>'}</div></div><div class="chart-headline"><div><span>REVENUE</span><strong class="positive">${rup(summary.income)}</strong></div>${revenueOnly?'':`<div><span>EXPENSES</span><strong class="negative">${rup(summary.expense)}</strong></div>`}</div>${data.length?`<div class="analytic-plot"><div class="chart-y-axis" aria-hidden="true"><span>${compact(rawMax)}</span><span>${compact(rawMax/2)}</span><span>Rp 0</span></div><div class="chart-scroll"><div class="chart" role="group" style="--plot-columns:${data.length}" aria-label="${revenueOnly?'Revenue per periode':'Revenue dan Expenses per periode'}">${data.map(r=>`<div class="chart-col ${r.key==='unassigned'?'chart-combined':''}"><div class="bars"><button type="button" class="bar" data-chart-month="${r.key}" data-chart-series="income" data-tooltip-label="${financialPeriodLabel(r.key)} · Revenue" data-tooltip-value="${rup(r.income)}" style="height:${r.income/max*100}%" aria-label="${financialPeriodLabel(r.key)}, Revenue ${rup(r.income)}. Tampilkan rincian."></button>${revenueOnly?'':`<button type="button" class="bar out" data-chart-month="${r.key}" data-chart-series="expense" data-tooltip-label="${financialPeriodLabel(r.key)} · Expenses" data-tooltip-value="${rup(r.expense)}" style="height:${r.expense/max*100}%" aria-label="${financialPeriodLabel(r.key)}, Expenses ${rup(r.expense)}. Tampilkan rincian."></button>`}</div><small>${r.key==='unassigned'?'Gabungan':esc(financialPeriodLabel(r.key))}</small></div>`).join('')}</div></div></div>`:'<div class="distribution-empty">Belum terdapat transaksi pada periode terpilih.</div>'}${showRit?renderRitChart(rs,truck):''}<div class="panel-foot"><span>Klik grafik untuk rincian. Gabungan memuat transaksi lintas bulan atau tanpa bulan tunggal; nilainya tidak dibagi berdasarkan perkiraan.</span></div></section>`;
}
function costPanel(rs){const costs=Object.entries(rs.reduce((a,t)=>{if(t.type==='Pengeluaran'&&t.expense)a[categoryLabel(t.category)]=(a[categoryLabel(t.category)]||0)+t.expense;return a;},{})).sort((a,b)=>b[1]-a[1]);const total=totals(rs).expense;return `<section class="panel"><div class="panel-head"><div><h3>Biaya terbesar</h3><div class="subtitle">${rup(total)} · klik kategori untuk rincian</div></div><button type="button" class="text-btn" data-cost-category="" aria-label="Lihat semua rincian biaya">${icon('arrow')}</button></div><div class="cost-list">${costs.slice(0,6).map(([cat,v],i)=>`<button type="button" class="cost-item" data-cost-category="${esc(cat)}" aria-label="Rincian biaya ${esc(cat)}, ${rup(v)}"><span class="cost-line"><span>${esc(cat)}</span><strong>${compact(v)}</strong></span><span class="track"><span class="fill" style="width:${v/(total||1)*100}%;opacity:${1-i*.1}"></span></span></button>`).join('')||'<div class="empty">Belum ada expenses pada periode ini.</div>'}</div></section>`;}
function detailScope(){return [scopeLabel(),truck==='all'?'Semua armada':truck,client==='all'?'Semua klien':cname(client)].map(esc).join(' · ');}
function detailModal(title,content,tone='neutral'){hideChartTooltip();formKind='';formId='';modal.classList.add('detail-dialog');modal.dataset.tone=tone;modal.setAttribute('aria-labelledby','detail-title');modal.innerHTML=`<div class="modal-head"><h2 id="detail-title">${esc(title)}</h2><button type="button" class="close" data-action="close" aria-label="Tutup rincian">×</button></div><div class="detail-content">${content}</div><div class="form-foot"><button type="button" class="btn" data-action="close">Tutup</button></div>`;modal.showModal();modal.scrollTop=0;}
function openCostDetails(category){if(category&&!expenseCategories.includes(category))return;const rows=scoped().filter(t=>t.type==='Pengeluaran'&&(t.expense??0)>0&&(!category||categoryLabel(t.category)===category)).sort((a,b)=>b.expense-a.expense||(a.date||'').localeCompare(b.date||'')||a.id.localeCompare(b.id));const sum=totals(rows).expense,showUnit=truck==='all';const units=[...new Set(rows.map(t=>t.plate))].map(plate=>({plate,total:totals(rows.filter(t=>t.plate===plate)).expense})).sort((a,b)=>b.total-a.total);detailModal(category?'Rincian biaya · '+category:'Semua biaya terbesar',`<p class="detail-scope">${detailScope()}</p><div class="detail-stats"><div><span>Total biaya</span><strong>${rup(sum)}</strong></div><div><span>Catatan biaya</span><strong>${rows.length} catatan</strong></div><div><span>Transaksi terbesar</span><strong>${rows.length?rup(rows[0].expense):'—'}</strong></div></div>${showUnit&&units.length?`<h3>Expenses per unit</h3><div class="table-wrap"><table class="detail-units"><thead><tr><th>Unit</th><th class="number">Total biaya</th></tr></thead><tbody>${units.map(u=>`<tr><td>${esc(u.plate)}</td><td class="number tx-amount tx-expense">${rup(u.total)}</td></tr>`).join('')}</tbody></table></div>`:''}<h3>Transaksi dari nominal terbesar</h3><p class="subtitle">Nominal kosong dan nol tidak masuk daftar biaya terbesar.</p><div class="table-wrap"><table class="detail-transactions"><thead><tr><th>Tanggal / Periode</th>${showUnit?'<th>Unit</th>':''}<th>Keterangan</th>${!category?'<th>Kategori</th>':''}<th class="number">Biaya</th></tr></thead><tbody>${rows.map(t=>`<tr><td class="wrap-cell">${fmt(t.date)}${!t.date?`<br><small>${esc(t.period)}</small>`:''}</td>${showUnit?`<td>${esc(t.plate)}</td>`:''}<td class="wrap-cell">${esc(t.description)}${t.customer?`<br><small>Klien: ${esc(clientName(t.customer))}</small>`:''}</td>${!category?`<td class="wrap-cell">${esc(categoryTitle(t.category))}</td>`:''}<td class="number tx-amount tx-expense" data-expense="${t.expense}">${rup(t.expense)}</td></tr>`).join('')||`<tr><td colspan="${(showUnit?1:0)+(category?0:1)+3}">Belum ada biaya untuk pilihan ini.</td></tr>`}</tbody></table></div>`,'expense');}
function openRitDetails(plate){if(!plates.includes(plate))return;const rows=scoped().filter(t=>t.plate===plate&&t.type==='Pemasukan'),t=totals(rows);detailModal('Rit tercatat · '+plate,`<p class="detail-scope">${detailScope()}</p><div class="detail-stats"><div class="selected"><span>Total rit</span><strong>${t.rit.toLocaleString('id-ID')} rit</strong></div><div><span>Transaksi Revenue</span><strong>${rows.length.toLocaleString('id-ID')}</strong></div><div class="income-stat"><span>Revenue tercatat</span><strong>${rup(t.income)}</strong></div></div><h3>Catatan Revenue ${esc(plate)}</h3>${txTable([...rows].sort(sortTx).slice(0,25),{revenueOnly:true})}<p class="detail-method">Rit mengikuti transaksi Revenue pada filter aktif. Hingga 25 catatan terbaru ditampilkan.</p>`);}
function openChartDetails(key,series){if((key!=='unassigned'&&!/^\d{4}-(0[1-9]|1[0-2])$/.test(key))||!['income','expense'].includes(series))return;const revenueOnly=page==='clients',rows=scoped().filter(t=>(key==='unassigned'?!monthKey(t):monthKey(t)===key)&&(!revenueOnly||t.type==='Pemasukan')),t=totals(rows);const units=[...new Set(rows.map(r=>r.plate))].map(plate=>({plate,...totals(rows.filter(r=>r.plate===plate))})).sort((a,b)=>b[series]-a[series]);if(revenueOnly)return detailModal(financialPeriodLabel(key)+' · Revenue',`<p class="detail-scope">${detailScope()}</p><div class="detail-stats"><div class="income-stat selected"><span>Revenue tercatat</span><strong data-chart-value="income">${rup(t.income)}</strong></div><div><span>Volume layanan</span><strong>${t.rit.toLocaleString('id-ID')} rit</strong></div><div><span>Transaksi revenue</span><strong>${t.count.toLocaleString('id-ID')}</strong></div></div><h3>Revenue per armada</h3><div class="table-wrap"><table><thead><tr><th>Armada</th><th class="number">Revenue</th><th class="number">Rit</th></tr></thead><tbody>${units.map(u=>`<tr><td>${esc(u.plate)}</td><td class="number tx-amount tx-income">${rup(u.income)}</td><td class="number">${u.rit.toLocaleString('id-ID')}</td></tr>`).join('')}</tbody></table></div>${t.missing?`<p class="detail-method">${t.missing} nominal revenue belum diisi. Total mengikuti nominal yang tersedia.</p>`:''}`,'income');detailModal(financialPeriodLabel(key)+' · '+(series==='income'?'Revenue':'Expenses'),`<p class="detail-scope">${detailScope()}</p><div class="detail-stats"><div class="income-stat ${series==='income'?'selected':''}"><span>Revenue tercatat</span><strong data-chart-value="income">${rup(t.income)}</strong></div><div class="expense-stat ${series==='expense'?'selected':''}"><span>Expenses tercatat</span><strong data-chart-value="expense">${rup(t.expense)}</strong></div><div><span>Selisih tercatat</span><strong>${rup(t.income-t.expense)}</strong></div></div><p>${t.count} transaksi · ${t.rit} rit · ${t.missing} nominal belum diisi</p>${truck==='all'&&units.length?`<h3>Angka per unit</h3><div class="table-wrap"><table><thead><tr><th>Unit</th><th class="number">Revenue</th><th class="number">Expenses</th></tr></thead><tbody>${units.map(u=>`<tr><td>${esc(u.plate)}</td><td class="number tx-amount tx-income">${rup(u.income)}</td><td class="number tx-amount tx-expense">${rup(u.expense)}</td></tr>`).join('')}</tbody></table></div>`:''}${key==='unassigned'?`<h3>Periode sumber</h3><div class="detail-unit-tags">${[...new Set(rows.map(r=>r.period||'Periode belum diisi'))].map(p=>`<span>${esc(p)}</span>`).join('')}</div>`:''}<p class="detail-method">Angka mengikuti filter aktif dan hanya menghitung nominal yang sudah diisi. Transaksi tanpa tanggal memakai label bulan tunggal yang jelas; periode gabungan tidak dialokasikan. Selisih tercatat bukan laba bersih akuntansi.</p>`,series);}
function clientDonut(rows){const {total,missing,parts}=revenueDistribution(rows),palette=['#17365d','#b78429','#8296af','#527196','#a38b5f','#b3bdcb'],radius=88,circ=2*Math.PI*radius;let offset=0;return `<aside class="client-distribution panel"><div class="distribution-heading"><h3>Komposisi Revenue</h3><span>${parts.length} klien · ${esc(scopeLabel())}</span></div><div class="donut-visual"><svg viewBox="0 0 240 240" class="revenue-donut" role="group" aria-label="Kontribusi revenue per klien"><circle cx="120" cy="120" r="${radius}" fill="none" stroke="#e9eef5" stroke-width="23"/>${parts.map((part,i)=>{const length=part.share*circ,result=`<circle class="donut-segment" cx="120" cy="120" r="${radius}" fill="none" stroke="${palette[i%palette.length]}" stroke-width="23" stroke-dasharray="${Math.max(0,length-2.5)} ${circ}" stroke-dashoffset="${-offset}" transform="rotate(-90 120 120)" role="button" tabindex="0" data-donut-client="${esc(part.key)}" data-tooltip-label="${esc(part.name)} · Revenue" data-tooltip-value="${rup(part.value)}" data-tooltip-meta="${(part.share*100).toLocaleString('id-ID',{maximumFractionDigits:1})}% dari total revenue" data-tooltip-tone="client" data-tooltip-color="${palette[i%palette.length]}" aria-label="${esc(part.name)}: ${rup(part.value)}, ${(part.share*100).toLocaleString('id-ID',{maximumFractionDigits:1})} persen"></circle>`;offset+=length;return result;}).join('')}</svg><div class="donut-center ${rup(total).length>17?'large-value':''}"><span>TOTAL REVENUE</span><strong>${rup(total)}</strong></div></div><div class="donut-legend">${parts.map((part,i)=>`<button class="donut-legend-row" data-donut-client="${esc(part.key)}" data-tooltip-label="${esc(part.name)} · Revenue" data-tooltip-value="${rup(part.value)}" data-tooltip-meta="${(part.share*100).toLocaleString('id-ID',{maximumFractionDigits:1})}% dari total revenue" data-tooltip-tone="client" data-tooltip-color="${palette[i%palette.length]}">${clientLogo(part.key,'client-logo-mini')||`<span class="donut-swatch" style="--segment-color:${palette[i%palette.length]}"></span>`}<span class="donut-client-name">${esc(part.name)}</span><span class="donut-legend-value"><strong>${rup(part.value)}</strong><small>${(part.share*100).toLocaleString('id-ID',{maximumFractionDigits:1})}%</small></span></button>`).join('')||'<p class="distribution-empty">Belum terdapat revenue pada filter terpilih.</p>'}</div>${missing?`<div class="distribution-note">${missing.toLocaleString('id-ID')} nominal revenue belum tersedia.</div>`:''}</aside>`;}
function selectDonutClient(key){const rows=scoped().filter(t=>t.type==='Pemasukan'&&clientKey(t.customer)===key),t=totals(rows),distribution=revenueDistribution(scoped()),share=distribution.total?t.income/distribution.total*100:0,units=[...new Set(rows.map(r=>r.plate))];detailModal(key?cname(key)+' · Revenue':'Revenue tanpa klien',`${clientLogo(key,'client-dialog-logo')}<p class="detail-scope">${detailScope()}</p><div class="detail-stats"><div class="income-stat selected"><span>Revenue tercatat</span><strong>${rup(t.income)}</strong></div><div><span>Kontribusi revenue</span><strong>${share.toLocaleString('id-ID',{maximumFractionDigits:1})}%</strong></div><div><span>Volume layanan</span><strong>${t.rit.toLocaleString('id-ID')} rit</strong></div></div><h3>Armada yang melayani</h3><div class="detail-unit-tags">${units.map(p=>`<span>${esc(p)}</span>`).join('')}</div><p>${rows.length.toLocaleString('id-ID')} transaksi revenue${t.missing?` · ${t.missing} nominal belum diisi`:''}</p><h3>Transaksi revenue</h3><p class="subtitle">Hingga 25 catatan terbaru pada filter terpilih.</p>${txTable([...rows].sort(sortTx).slice(0,25))}${key?`<button class="btn primary detail-client-link" data-client="${esc(key)}">Buka rincian klien ${icon('arrow')}</button>`:''}`,'income');}
function clientTable(rs,{compactMode=false}={}){const cs=clientSummary(rs).filter(c=>c.incomeRows);const total=totals(rs).income;return `<section class="panel"><div class="panel-head"><div><h3>Revenue per Klien</h3><div class="subtitle">${esc(scopeLabel())}</div></div><button class="text-btn" data-page="clients">Analisis klien ↗</button></div>${cs.length?`<div class="table-wrap"><table><thead><tr><th>Klien</th><th class="number">Revenue tercatat</th><th class="number">Kontribusi</th><th class="number">Rit</th><th>Armada</th><th></th></tr></thead><tbody>${cs.slice(0,compactMode?5:cs.length).map((c,i)=>`<tr><td><span class="client-label">${clientLogo(c.name)||`<span class="client-avatar tone-${i%4}">${esc(c.name.slice(0,2).toUpperCase())}</span>`}<strong>${esc(c.name)}</strong></span></td><td class="number"><strong>${rup(c.income)}</strong></td><td class="number">${total?(c.income/total*100).toLocaleString('id-ID',{maximumFractionDigits:1})+'%':'—'}</td><td class="number">${c.rit}</td><td>${c.plates.length} truk</td><td><button class="text-btn" data-client="${esc(c.key)}">Detail ↗</button></td></tr>`).join('')}</tbody></table></div>`:emptyBlock('Klien akan terlihat di sini.','Hubungkan revenue ke klien saat menambahkan transaksi.','add-client','Tambah klien')}<div class="panel-foot"><span>Nominal kosong belum masuk total.</span><span>${cs.length} klien dengan revenue tercatat</span></div></section>`;}
function truckTable(rs,{revenueOnly=false}={}){return `<section class="panel"><div class="panel-head"><div><h3>${client==='all'?'Kinerja armada':'Kontribusi armada untuk '+esc(cname(client))}</h3><div class="subtitle">${esc(scopeLabel())}</div></div><button class="text-btn" data-page="fleet">Lihat armada ↗</button></div><div class="table-wrap"><table><thead><tr><th>Armada</th><th>Status</th><th class="number">Revenue</th>${revenueOnly?'':`<th class="number">Expenses${client!=='all'?' terkait':''}</th><th class="number">Selisih</th>`}<th class="number">Rit</th><th></th></tr></thead><tbody>${state.fleet.filter(f=>(truck==='all'||f.plate===truck)&&(!revenueOnly||rs.some(t=>t.plate===f.plate))).map(f=>{const r=rs.filter(t=>t.plate===f.plate),t=totals(r);return `<tr><td><span class="plate"><span class="plate-icon">${icon('truck')}</span>${f.plate}</span></td><td>${badge(f.status)}</td><td class="number">${rup(t.income)}</td>${revenueOnly?'':`<td class="number">${rup(t.expense)}</td><td class="number ${t.income<t.expense?'negative':'positive'}">${rup(t.income-t.expense)}</td>`}<td class="number">${t.rit}</td><td><button class="text-btn" data-truck="${f.plate}">Transaksi ↗</button></td></tr>`;}).join('')||`<tr><td colspan="${revenueOnly?5:7}" class="empty">Belum ada transaksi pada filter ini.</td></tr>`}</tbody></table></div></section>`;}
function dashboard(){const rs=scoped(),cs=clientSummary(rs).filter(c=>c.incomeRows);return `<div class="overview-page"><div class="overview-summary"><strong>Ikhtisar Kinerja Bisnis</strong><div><span>${rs.length.toLocaleString('id-ID')} transaksi</span><span>${plates.length.toLocaleString('id-ID')} armada</span><span>${cs.length.toLocaleString('id-ID')} klien</span></div></div>${filters()}${financeStats(rs)}<div class="overview-chart-grid">${incomeChart(rs,{showRit:true})}${clientDonut(rs)}</div><div class="overview-detail-grid">${costPanel(rs)}${truckTable(rs)}</div>${dataNotice(rs)}</div>`;}

function clients(){const rs=scoped().filter(t=>t.type==='Pemasukan'),cs=clientSummary(rs,client==='all'?state.clients:state.clients.filter(c=>clientKey(c.name)===client)),total=totals(rs),known=cs.filter(c=>c.incomeRows),missing=rs.filter(t=>t.type==='Pemasukan'&&!clientKey(t.customer));const incomeRows=rs.filter(t=>t.type==='Pemasukan'),linkedIncome=cs.reduce((n,c)=>n+c.income,0),units=new Set(incomeRows.filter(t=>clientKey(t.customer)).map(t=>t.plate)).size;const master=state.clients.find(c=>clientKey(c.name)===client);const cards=cs.filter(c=>c.rows.length||state.clients.some(m=>clientKey(m.name)===c.key));return `<div class="clients-page"><section class="clients-overview"><div class="clients-intro">${client!=='all'?clientLogo(client,'client-profile-logo'):''}<span class="clients-kicker">${client==='all'?'PORTOFOLIO KLIEN':'PROFIL DAN KINERJA KLIEN'}</span><h2>${client==='all'?'Analisis Revenue<br>dan Kontribusi Klien':esc(cname(client))}</h2><p>${client==='all'?'Analisis kontribusi revenue, volume rit, dan distribusi layanan armada untuk setiap klien.':esc(master?.contact||'Kontak belum dicatat')}${client!=='all'&&master?.notes?`<br>${esc(master.notes)}`:''}</p>${client!=='all'?`<button class="btn client-profile-edit" data-profile="${esc(client)}">${icon('clients')}Edit profil klien</button>`:''}</div><div class="clients-overview-numbers"><span>Revenue ${client==='all'?'terkait klien':'klien'}</span><strong>${rup(linkedIncome)}</strong><small>${esc(scopeLabel())} · ${truck==='all'?'Semua armada':esc(truck)}</small><div class="clients-mini-metrics"><div><b>${client==='all'?known.length:totals(incomeRows).rit}</b><span>${client==='all'?'klien bertransaksi':'rit tercatat'}</span></div><div><b>${units}</b><span>armada melayani</span></div><div><b>${incomeRows.length}</b><span>transaksi revenue</span></div></div></div></section><section class="client-filter-panel" aria-label="Filter portofolio klien"><div class="clients-section-heading"><span>${icon('clients')}Filter Analisis Klien</span></div>${filters()}</section>${client==='all'?`<div class="clients-directory-layout"><section class="clients-directory"><div class="clients-directory-title"><h2>Portofolio Klien</h2><span>${cards.length} profil</span></div><div class="client-grid">${cards.map((c,i)=>`<article class="panel client-card"><div class="client-card-head">${clientLogo(c.name)||`<span class="client-avatar tone-${i%4}">${esc(c.name.slice(0,2).toUpperCase())}</span>`}<span class="badge">${c.plates.length} armada</span></div><h3>${esc(c.name)}</h3><p>Revenue · ${esc(scopeLabel())}</p><strong class="client-value">${rup(c.income)}</strong><div class="client-mini"><span>${c.rit} rit tercatat</span><span>${c.incomeRows} transaksi revenue</span></div><div class="track"><div class="fill" style="width:${total.income?c.income/total.income*100:0}%"></div></div><div class="client-trucks">${c.plates.map(p=>`<span>${p}</span>`).join('')||'<span>Belum ada transaksi pada filter ini</span>'}</div><button class="btn client-detail" data-client="${esc(c.key)}">Rincian Klien ${icon('arrow')}</button></article>`).join('')||`<section class="panel client-card">${emptyBlock('Data Klien Belum Tersedia','Tambahkan profil klien dan hubungkan dengan transaksi revenue.','add-client','Tambah klien')}</section>`}</div></section></div>`:`<div class="client-revenue-analysis">${incomeChart(rs,{revenueOnly:true})}</div>${truckTable(rs,{revenueOnly:true})}<section class="panel section-gap"><div class="panel-head"><div><h3>Transaksi ${esc(cname(client))}</h3><div class="subtitle">${esc(scopeLabel())} · hingga 25 catatan terbaru</div></div><button class="text-btn" data-page="finance">Buka buku transaksi ↗</button></div>${txTable([...rs].sort(sortTx).slice(0,25),{revenueOnly:true})}</section>`}${missing.length?`<div class="notice">${icon('warning')}<div><strong>${missing.length} transaksi revenue belum memiliki klien.</strong> Hubungkan catatannya agar analisis klien lengkap. <button class="text-btn" data-action="unassigned-client">Tinjau →</button></div></div>`:''}</div>`;}
function sortTx(a,b){return (b.date||'').localeCompare(a.date||'')||b.id.localeCompare(a.id);}
function txTable(rs,{revenueOnly=false}={}){if(revenueOnly)rs=rs.filter(t=>t.type==='Pemasukan');return `<div class="table-wrap"><table><thead><tr><th>Tanggal / periode</th><th>Armada & keterangan</th><th>Jenis / kategori</th><th>Klien</th><th class="number">Revenue</th>${revenueOnly?'':'<th class="number">Expenses</th>'}<th class="number">Rit</th><th></th></tr></thead><tbody>${rs.map(t=>`<tr class="transaction-row ${t.type==='Pemasukan'?'income-row':'expense-row'} ${issues(t)?'review-row':''}"><td>${fmt(t.date)}<br><small class="muted">${esc(t.period)}</small>${dateIssue(t)?'<br><span class="badge red">Tanggal berbeda / di masa depan</span>':''}</td><td class="long"><strong>${t.plate}</strong><br><span title="${esc(t.description)}">${esc(t.description)}</span>${issues(t)?'<br><span class="badge amber">Perlu ditinjau</span>':''}</td><td>${badge(t.type)}<br><span>${esc(categoryTitle(t.category))}</span></td><td>${clientKey(t.customer)?`<button class="text-btn" data-client="${esc(clientKey(t.customer))}">${esc(clientName(t.customer))}</button>`:t.type==='Pemasukan'?'<span class="muted">Belum terkait</span>':''}</td><td class="number ${t.type==='Pemasukan'?'tx-amount tx-income':''}">${t.income===0?'—':rup(t.income)}</td>${revenueOnly?'':`<td class="number ${t.type==='Pengeluaran'?'tx-amount tx-expense':''}">${t.expense===0?'—':rup(t.expense)}</td>`}<td class="number">${t.rit||'—'}</td><td><button class="text-btn" data-edit="${esc(t.id)}">Edit</button></td></tr>`).join('')||`<tr><td colspan="${revenueOnly?7:8}" class="empty">Tidak ada transaksi sesuai filter.</td></tr>`}</tbody></table></div>`;}
function finance(){const rs=scoped(),filtered=[...rs].filter(t=>(quality==='all'||quality==='review'&&issues(t)||quality==='client'&&t.type==='Pemasukan'&&!clientKey(t.customer))&&(type==='all'||t.type===type)&&[t.description,clientName(t.customer),t.plate,t.category].join(' ').toLowerCase().includes(search.toLowerCase())).sort(sortTx);offset=Math.min(offset,Math.max(0,Math.floor((filtered.length-1)/25)*25));const summary=totals(rs);return `<div class="ledger-page"><div class="ledger-heading"><div><span class="ledger-kicker">CATATAN KAS & AKTIVITAS</span><h2>Rekapitulasi Transaksi Keuangan</h2></div><div class="ledger-record-count"><strong>${filtered.length}</strong><span>transaksi sesuai filter</span></div></div><section class="ledger-summary" aria-label="Ringkasan transaksi"><div><span>Revenue tercatat</span><strong class="positive">${rup(summary.income)}</strong></div><div><span>Expenses tercatat</span><strong class="negative">${rup(summary.expense)}</strong></div><div><span>Selisih tercatat</span><strong class="${summary.income<summary.expense?'negative':'positive'}">${rup(summary.income-summary.expense)}</strong></div><button data-action="review" class="ledger-review">${icon('warning')}<span><b>${rs.filter(issues).length}</b> perlu ditinjau</span>${icon('arrow')}</button></section><div class="ledger-filters">${filters()}</div><section class="panel ledger-table-panel"><div class="panel-head"><div><h3>Daftar transaksi</h3><div class="subtitle">Cari catatan, cek nominal, atau lihat detail transaksinya.</div></div><span class="pill">${filtered.length} CATATAN</span></div><div class="toolbar"><input id="search" aria-label="Cari transaksi" value="${esc(search)}" placeholder="Cari keterangan, klien, atau armada…"><select id="type-filter" aria-label="Jenis transaksi"><option value="all">Semua jenis</option>${options(['Pemasukan','Pengeluaran'],type)}</select><select id="quality-filter" aria-label="Kelengkapan"><option value="all">Semua catatan</option><option value="review" ${quality==='review'?'selected':''}>Perlu dilengkapi</option><option value="client" ${quality==='client'?'selected':''}>Revenue tanpa klien</option></select></div>${txTable(filtered.slice(offset,offset+25))}<div class="panel-foot"><span>${filtered.length?offset+1:0}–${Math.min(offset+25,filtered.length)} dari ${filtered.length} catatan</span><div><button data-action="prev" ${!offset?'disabled':''}>← Sebelumnya</button> <button data-action="next" ${offset+25>=filtered.length?'disabled':''}>Berikutnya →</button></div></div></section>${dataNotice(rs)}</div>`;}
let fleetMotion=true;

function fleet(){const rs=scoped();return `${filters({clients:false})}<div class="fleet-motion-control"><button type="button" class="text-btn" data-action="fleet-motion" aria-pressed="${!fleetMotion}">${fleetMotion?'Jeda animasi':'Putar animasi'}</button></div><div class="fleet-grid ${fleetMotion?'':'motion-paused'}">${state.fleet.filter(f=>truck==='all'||f.plate===truck).map(f=>{const t=totals(rs.filter(r=>r.plate===f.plate)),cs=clientSummary(rs.filter(r=>r.plate===f.plate)).filter(c=>c.incomeRows);return `<article class="panel fleet-card"><div class="actions"><span class="plate">${f.plate}</span>${badge(f.status)}</div>${fleetIllustration(f.plate,f.status)}<div class="fleet-metrics"><div>Revenue<strong class="positive">${compact(t.income)}</strong></div><div>Biaya<strong class="negative">${compact(t.expense)}</strong></div><div>Rit<strong>${t.rit}</strong></div></div><div class="client-trucks">${cs.map(c=>`<button data-client="${esc(c.key)}">${esc(c.name)}</button>`).join('')||'<span>Belum ada klien pada filter ini</span>'}</div>${f.serviceDue||f.documentDue?`<p class="sub fleet-dates">${f.serviceDue?`<span>Servis: ${fmt(f.serviceDue)}</span>`:''}${f.documentDue?`<span>Dokumen: ${fmt(f.documentDue)}</span>`:''}</p>`:''}<div class="actions section-gap"><button class="btn small" data-fleet="${f.plate}">Perbarui armada</button><button class="text-btn" data-truck="${f.plate}">Keuangan ↗</button></div></article>`;}).join('')}</div>`;}
function trips(){const rs=state.trips.filter(t=>(truck==='all'||t.plate===truck)&&(client==='all'||clientKey(t.customer)===client)&&[t.plate,clientName(t.customer),t.driver,t.origin,t.destination].join(' ').toLowerCase().includes(search.toLowerCase()));return `<div class="operations-page"><div class="operations-map-grid"><section class="operations-map-shell panel"><div class="map-panel-heading"><div><h2>Jakarta Utara</h2><span>Wilayah operasional · Tanjung Priok</span></div><div class="map-view-buttons"><button class="btn small" data-map-view="north">Jakarta Utara</button><button class="btn small" data-map-view="port">Tanjung Priok</button></div></div><div id="operations-map" class="operations-map" role="region" aria-label="Peta Jakarta Utara termasuk Pelabuhan Tanjung Priok"></div><div class="map-foot"><span data-map-status>Memuat peta wilayah…</span><a href="https://www.openstreetmap.org/#map=12/-6.126/106.883" target="_blank" rel="noopener noreferrer">Buka peta ↗</a></div></section><aside class="ops-activity panel"><div class="ops-activity-title"><span>OPERASIONAL</span><h3>Status Perjalanan</h3></div>${['Terjadwal','Dalam perjalanan','Selesai','Dibatalkan'].map((status,i)=>`<div class="ops-status-row"><span class="ops-status-dot status-${i}"></span><span>${status}</span><strong>${rs.filter(t=>t.status===status).length.toLocaleString('id-ID')}</strong></div>`).join('')}<div class="ops-map-disclaimer">Peta referensi wilayah. Posisi GPS kendaraan belum terhubung.</div></aside></div>${filters({operational:true})}<section class="panel ops-trip-register"><div class="panel-head"><div><h3>Perjalanan & pengiriman</h3></div><span class="pill">${rs.length} TRIP</span></div><div class="toolbar"><input id="search" aria-label="Cari trip" value="${esc(search)}" placeholder="Cari klien, rute, driver…"></div>${rs.length?`<div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Armada / driver</th><th>Klien</th><th>Rute</th><th>Status</th><th></th></tr></thead><tbody>${[...rs].sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td>${fmt(t.date)}</td><td><strong>${t.plate}</strong><br>${esc(t.driver)}</td><td>${esc(clientName(t.customer))}</td><td>${esc(t.origin)} → ${esc(t.destination)}</td><td>${badge(t.status)}</td><td><button class="text-btn" data-trip="${esc(t.id)}">Perbarui</button></td></tr>`).join('')}</tbody></table></div>`:emptyBlock('Mulai catat perjalanan armada.','Tambahkan perjalanan untuk mencatat rute dan status pengiriman.','add-trip','Tambah trip')}</section></div>`;}

function reports(){return `<section class="hero"><div><div class="eyebrow">WEEKLY MANAGEMENT REPORT</div><h2>Laporan Kinerja Mingguan</h2><p>Ringkasan aktivitas operasional dan evaluasi transaksi untuk periode tujuh hari.</p></div><div class="hero-side">${icon('report')}</div></section><div class="report-list">${[...state.reports].sort((a,b)=>b.week.localeCompare(a.week)).map(r=>{const rs=weeklyRows(state,r.week),t=totals(rs);return `<article class="panel"><div class="report"><div class="report-date">${icon('calendar')}</div><div><h3>Minggu mulai ${fmt(r.week)}</h3><p>${esc(r.notes)||'Belum ada catatan evaluasi.'}</p>${badge(r.status)}</div><button class="btn small" data-report="${esc(r.id)}">Tinjau laporan</button></div><div class="week-summary">${rs.length} transaksi · Revenue ${rup(t.income)} · Expenses ${rup(t.expense)} · ${t.rit} rit<br><small class="muted">Transaksi tanpa tanggal tidak disertakan. Ringkasan mengikuti data terkini.</small></div></article>`;}).join('')||`<section class="panel">${emptyBlock('Belum ada laporan mingguan.','Pilih tanggal awal periode untuk menyusun laporan mingguan.','add-report','Buat laporan')}</section>`}</div>`;}
function reportSection(number,title,subtitle,id){return `<div class="report-section-title" id="${id}"><span>${number}</span><div><h3>${title}</h3><small>${subtitle}</small></div></div>`;}
function monthlyDetails(rows){return `${reportSection('05','Rincian Transaksi','Transaction Details','report-transactions')}<p class="report-table-caption">${rows.length} transaksi pada periode dan cakupan armada terpilih.</p><div class="table-wrap"><table class="monthly-transactions"><thead><tr><th>Tanggal</th><th>Armada / Keterangan</th><th>Jenis / Kategori</th><th>Klien</th><th class="number">Revenue</th><th class="number">Expenses</th></tr></thead><tbody>${[...rows].sort((a,b)=>(a.date||'').localeCompare(b.date||'')||a.description.localeCompare(b.description)).map(t=>`<tr><td>${fmt(t.date)}</td><td class="wrap-cell"><strong>${esc(t.plate)}</strong><br>${esc(t.description)}</td><td class="wrap-cell">${badge(t.type)}<br>${esc(categoryTitle(t.category))}</td><td class="wrap-cell">${esc(t.customer||'—')}</td><td class="number ${t.type==='Pemasukan'?'tx-amount tx-income':''}">${rup(t.income)}</td><td class="number ${t.type==='Pengeluaran'?'tx-amount tx-expense':''}">${rup(t.expense)}</td></tr>`).join('')||'<tr><td colspan="6">Tidak terdapat transaksi pada periode dan cakupan yang dipilih.</td></tr>'}</tbody></table></div>`;}
function monthly(){
 const rs=selectRows(state,{month:reportMonth,plate:reportTruck}),t=totals(rs),clients=clientSummary(rs).filter(c=>c.incomeRows);
 const note=state.monthlyReports.find(r=>monthlyReportKey(r)===monthlyReportKey({month:reportMonth,plate:reportTruck}));
 const prevMonth=previousMonth(reportMonth),prevRows=selectRows(state,{month:prevMonth,plate:reportTruck}),prev=totals(prevRows);
 const trend=reportTrend(state,reportMonth,reportTruck);
 const sumCategory=(rows,type,c)=>rows.filter(r=>r.type===type&&categoryLabel(r.category)===c).reduce((a,r)=>a+((type==='Pemasukan'?r.income:r.expense)??0),0);
 const costNames=expenseCategories.filter(c=>sumCategory(rs,'Pengeluaran',c)||sumCategory(prevRows,'Pengeluaran',c));
 const scope=reportTruck==='all'?'Seluruh armada':reportTruck;
 const incomeRow=c=>`<tr><td>${esc(financialLabel(c))}</td><td class="number report-current">${rup(sumCategory(rs,'Pemasukan',c))}</td><td class="number">${prevRows.length?rup(sumCategory(prevRows,'Pemasukan',c)):'—'}</td></tr>`;
 return `<div class="report-controls no-print"><div class="filter-group"><label class="filter-field"><span>PERIODE LAPORAN</span><input id="report-month" aria-label="Bulan laporan" type="month" value="${reportMonth}"></label><label class="filter-field"><span>CAKUPAN ARMADA</span><select id="report-truck" aria-label="Truk laporan bulanan"><option value="all">Seluruh armada</option>${options(plates,reportTruck)}</select></label></div><div class="actions"><button class="btn" data-action="edit-monthly">${icon('report')}Catatan internal</button><button class="btn" data-action="monthly-csv">${icon('download')}Unduh CSV</button><button class="btn primary" data-action="print">${icon('print')}Cetak / Simpan PDF</button></div></div>
 ${note?.notes?`<aside class="report-internal-note no-print"><strong>Catatan internal</strong><p>${esc(note.notes).replaceAll('\n','<br>')}</p></aside>`:''}<article class="monthly-sheet corporate-report"><header class="monthly-header"><div class="report-brand"><img src="/brand/logo-mark.png" alt=""><div>PT JAYA BINTANG TERANG<small>LOGISTICS & CONTAINER SOLUTIONS</small></div></div><div class="monthly-id"><span>LAPORAN MANAJEMEN</span><strong>${monthLabel(reportMonth)}</strong>${badge(note?.status||'Draft')}</div></header>
 <div class="monthly-title"><div class="eyebrow">MONTHLY MANAGEMENT REPORT</div><h2>Laporan Manajemen<br>Bulanan</h2><p class="report-subtitle">Ikhtisar Revenue dan Expenses</p><div class="report-meta"><div><span>Periode pelaporan</span><strong>${monthLabel(reportMonth)}</strong></div><div><span>Cakupan laporan</span><strong>${esc(scope)}</strong></div><div><span>Satuan penyajian</span><strong>Rupiah (IDR)</strong></div></div></div>
 <nav class="report-toc no-print" aria-label="Bagian laporan"><a href="#report-financial">01 Ikhtisar Keuangan</a><a href="#report-clients">02 Revenue per Klien</a><a href="#report-fleet">03 Kinerja Armada</a><a href="#report-trend">04 Tren Tiga Bulan</a><a href="#report-transactions">05 Transaksi</a></nav>
 ${!rs.length?'<div class="notice">Tidak terdapat transaksi untuk periode dan armada yang dipilih. Nilai nol menunjukkan belum adanya catatan, bukan konfirmasi tidak adanya aktivitas.</div>':''}
 <div class="monthly-kpis"><div><span>REVENUE TERCATAT</span><strong>${rup(t.income)}</strong></div><div><span>EXPENSES TERCATAT</span><strong>${rup(t.expense)}</strong></div><div class="${t.income<t.expense?'negative':'positive'}"><span>SELISIH TERCATAT</span><strong>${rup(t.income-t.expense)}</strong></div></div>
 ${reportSection('01','Ikhtisar Keuangan','Financial Highlights','report-financial')}<p class="report-table-caption">Perbandingan transaksi tercatat dengan periode sebelumnya. Seluruh nominal disajikan dalam Rupiah.</p>
 <div class="table-wrap"><table class="report-financial"><thead><tr><th>Uraian</th><th class="number report-current">${monthLabel(reportMonth)}</th><th class="number">${monthLabel(prevMonth)}</th></tr></thead><tbody><tr class="report-group"><td colspan="3">REVENUE</td></tr>${incomeCategories.map(incomeRow).join('')}<tr class="report-total"><td>Total Revenue Tercatat</td><td class="number report-current">${rup(t.income)}</td><td class="number">${prevRows.length?rup(prev.income):'—'}</td></tr><tr class="report-group"><td colspan="3">EXPENSES</td></tr>${costNames.map(c=>`<tr><td>${esc(c)}</td><td class="number report-current">${rup(sumCategory(rs,'Pengeluaran',c))}</td><td class="number">${prevRows.length?rup(sumCategory(prevRows,'Pengeluaran',c)):'—'}</td></tr>`).join('')||'<tr><td colspan="3">Tidak terdapat expenses tercatat.</td></tr>'}<tr class="report-total"><td>Total Expenses Tercatat</td><td class="number report-current">${rup(t.expense)}</td><td class="number">${prevRows.length?rup(prev.expense):'—'}</td></tr><tr class="report-net"><td>Selisih Revenue dan Expenses</td><td class="number report-current">${rup(t.income-t.expense)}</td><td class="number">${prevRows.length?rup(prev.income-prev.expense):'—'}</td></tr></tbody></table></div><p class="report-table-note">Tanda (—) pada periode pembanding menunjukkan tidak tersedianya catatan. Selisih tercatat tidak merepresentasikan laba bersih.</p>
 ${reportSection('02','Revenue per Klien','Client Revenue Contribution','report-clients')}<div class="table-wrap"><table><thead><tr><th>Klien</th><th>Armada</th><th class="number">Rit</th><th class="number report-current">Revenue Tercatat</th></tr></thead><tbody>${clients.map(c=>`<tr><td><span class="client-report-identity">${clientLogo(c.name)}<strong>${esc(c.name)}</strong></span></td><td class="wrap-cell">${c.plates.map(esc).join(', ')}</td><td class="number">${c.rit}</td><td class="number report-current">${rup(c.income)}</td></tr>`).join('')||'<tr><td colspan="4">Tidak terdapat revenue klien tercatat.</td></tr>'}${rs.some(r=>r.type==='Pemasukan'&&!clientKey(r.customer))?`<tr><td>Klien belum ditetapkan</td><td>—</td><td class="number">${totals(rs.filter(r=>r.type==='Pemasukan'&&!clientKey(r.customer))).rit}</td><td class="number report-current">${rup(totals(rs.filter(r=>r.type==='Pemasukan'&&!clientKey(r.customer))).income)}</td></tr>`:''}</tbody></table></div>
 ${reportSection('03','Kinerja Armada','Fleet Performance','report-fleet')}<p class="report-table-caption">Cakupan: ${esc(scope)}.</p><div class="table-wrap"><table><thead><tr><th>Armada</th><th class="number">Revenue</th><th class="number">Expenses</th><th class="number">Selisih</th><th class="number">Rit</th></tr></thead><tbody>${(reportTruck==='all'?plates:[reportTruck]).map(p=>{const a=totals(rs.filter(r=>r.plate===p));return `<tr><td>${esc(p)}</td><td class="number">${rup(a.income)}</td><td class="number">${rup(a.expense)}</td><td class="number">${rup(a.income-a.expense)}</td><td class="number">${a.rit}</td></tr>`;}).join('')}</tbody></table></div>
 ${reportSection('04','Perkembangan Revenue dan Expenses','Three-Month Performance','report-trend')}${renderReportTrend(trend)}
 ${monthlyDetails(rs)}<footer class="monthly-footer"><div>Disusun oleh<strong>${esc(note?.preparedBy||'Belum ditetapkan')}</strong></div><div>Status Penelaahan<strong>${esc(note?.status||'Draft')}</strong></div><div>Tanggal Penyajian<strong>${fmt(today())}</strong></div></footer><div class="report-endnote">PT JAYA BINTANG TERANG <span>Laporan Manajemen Bulanan · ${monthLabel(reportMonth)} · ${esc(scope)}</span></div></article>`;
}

function settings(){return `<div class="storage-banner"><span class="storage-icon">${icon('settings')}</span><div><strong>${status.storage==='browser'?'Data tersimpan di browser ini':status.storage==='cloud'?'Database bersama terhubung':'Data tersimpan di komputer ini'}</strong><p>${status.storage==='browser'?'Data tidak otomatis pindah ke browser atau perangkat lain. Unduh cadangan secara berkala.':'Ruang kerja ini hanya bisa dibuka oleh email tim yang sudah terdaftar.'}</p></div></div><div class="setup-grid"><section class="panel setup-card"><h3>Masukkan data atau cadangan</h3><p>Masukkan file hasil konversi Excel atau cadangan aplikasi. Catatan yang sudah ada tidak akan ditambahkan dua kali.</p><button class="btn primary" data-action="import">${icon('plus')}Pilih file JSON</button></section><section class="panel setup-card"><h3>Cadangan data</h3><p>Satu file cadangan menyimpan transaksi, klien, armada, perjalanan, dan catatan laporan. Simpan untuk berjaga-jaga atau pindahkan ke perangkat lain.</p><div class="actions"><button class="btn primary" data-action="backup">${icon('download')}Unduh cadangan</button><button class="btn" data-action="export">Ekspor CSV</button></div></section><section class="panel setup-card"><h3>Tentang ruang kerja ini</h3><p>Revisi: ${state.revision}<br>Transaksi: ${state.transactions.length}<br>Armada: ${plates.length}<br>Terakhir disimpan: ${state.updatedAt?new Date(state.updatedAt).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'}):'Belum ada perubahan'}</p><button class="btn" data-action="reload">${icon('refresh')}Muat ulang</button></section><section class="panel setup-card"><h3>Dasar laporan</h3><p>Revenue dan expenses memiliki kategori terpisah. Klien wajib diisi untuk transaksi revenue baru. Biaya umum tidak otomatis dialokasikan ke klien.</p><p>Laporan bulanan menggunakan tanggal atau label bulan tunggal yang jelas. Periode gabungan tetap terpisah. Laporan bukan pengganti buku besar akuntansi.</p></section></div><section class="panel section-gap"><div class="panel-head"><div><h3>Riwayat penyimpanan</h3><div class="subtitle">Lihat kapan data terakhir disimpan.</div></div></div><div class="table-wrap"><table><thead><tr><th>Waktu WIB</th><th>Aktivitas</th><th class="number">Transaksi</th><th class="number">Trip</th></tr></thead><tbody>${state.audit.slice(0,15).map(a=>`<tr><td>${esc(new Date(a.at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'}))}</td><td>${esc(a.action)}</td><td class="number">${a.transactions}</td><td class="number">${a.trips}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Belum ada riwayat.</td></tr>'}</tbody></table></div></section>`;}
function closeNavigation(restore=true){$('.sidebar')?.classList.remove('open');$('.nav-scrim')?.setAttribute('hidden','');$('.mobile-menu')?.setAttribute('aria-expanded','false');$('.workspace')?.removeAttribute('inert');document.body.classList.remove('menu-open');if(restore)$('.mobile-menu')?.focus();}
function openNavigation(){if(!matchMedia('(max-width:650px)').matches)return;$('.sidebar').classList.add('open');$('.nav-scrim').removeAttribute('hidden');$('.mobile-menu').setAttribute('aria-expanded','true');$('.workspace').setAttribute('inert','');document.body.classList.add('menu-open');$('.nav-dismiss').focus();}
document.addEventListener('keydown',e=>{if(!document.body.classList.contains('menu-open'))return;if(e.key==='Escape'){e.preventDefault();closeNavigation();}if(e.key==='Tab'){const items=[...document.querySelectorAll('.sidebar button')].filter(n=>n.getClientRects().length&&!n.disabled),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
matchMedia('(max-width:650px)').addEventListener('change',e=>{if(!e.matches)closeNavigation(false);});
let mapCleanup=null;
function render(){hideChartTooltip();if(!state)return;if(mapCleanup){mapCleanup();mapCleanup=null;}document.body.dataset.page=page;document.body.classList.remove('menu-open');const focused=document.activeElement?.id;const button=page==='clients'?['add-client','Tambah klien']:page==='trips'?['add-trip','Tambah trip']:page==='reports'?['add-report','Buat laporan']:['add-tx','Tambah transaksi'];app.innerHTML=`<a class="skip-link" href="#main-content">Langsung ke isi halaman</a><button type="button" class="nav-scrim" data-action="close-menu" aria-label="Tutup menu navigasi" hidden></button><aside class="sidebar" id="site-navigation" aria-label="Navigasi utama"><div class="mobile-nav-top"><span>Menu utama</span><button class="nav-dismiss" data-action="close-menu" aria-label="Tutup menu">×</button></div><div class="brand"><img src="/brand/logo-mark.png" alt=""><div><strong>PT Jaya Bintang<br>Terang</strong><small>JBT · LOGISTICS</small></div></div><div class="nav-label">KELOLA BISNIS</div><nav>${[['dashboard','dashboard'],['clients','clients'],['finance','finance'],['sheets','file'],['fleet','truck'],['control','trip'],['trips','trip']].map(([p,i])=>`<button data-page="${p}" aria-current="${page===p?'page':'false'}" class="${page===p?'active':''}">${icon(i)}${names[p]}${p==='sheets'?`<span class="sheet-nav-dirty" data-sheet-dirty ${sheetEditor.dirty?'':'hidden'}>Draft</span>`:''}</button>`).join('')}</nav><div class="nav-label section-gap">LAPORAN</div><nav>${[['monthly','file'],['reports','report']].map(([p,i])=>`<button data-page="${p}" aria-current="${page===p?'page':'false'}" class="${page===p?'active':''}">${icon(i)}${names[p]}${p==='monthly'?'<span class="nav-new">PDF</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><button data-page="settings" class="sidebar-settings">${icon('settings')}Data & cadangan</button>${status.access==='email'||status.sessionAuthenticated?'<button class="sidebar-settings" data-action="logout">Keluar</button>':''}<span class="live-dot"></span><strong>${status.storage==='browser'?'Tersimpan di browser':status.storage==='cloud'?'Database bersama':'Tersimpan di perangkat'}</strong><br><span>${status.access==='email'?'Akses email':'Data di browser ini'} · Backup berkala</span></div></aside><div class="workspace page-${page}"><header class="topbar"><div class="actions"><button class="mobile-menu" data-action="menu" aria-label="Buka menu" aria-controls="site-navigation" aria-expanded="false">${icon('menu')}</button><span class="crumb">Ruang kerja &nbsp; / &nbsp; <b>${names[page]}</b></span></div><div class="top-tools">${status.googleLogin&&status.access==='browser'&&!status.sessionAuthenticated?'<a class="btn small google-nav-login" href="/?login=google">Masuk dengan Google</a>':''}${status.sessionAuthenticated?'<span class="session-account">Akun tim terhubung</span>':''}<span><span class="live-dot"></span>${page==='control'?'Kontrol rit di database bersama':status.storage==='browser'?'Data di browser ini':'Tersimpan'}${status.offline?' · Offline':''}</span><button class="top-backup" data-action="backup" title="Unduh cadangan" aria-label="Unduh cadangan">${icon('download')}</button><span class="avatar" aria-label="Jaya Bintang Terang">JBT</span></div></header><main id="main-content" tabindex="-1"><div class="heading no-print"><div class="heading-main"><span class="page-emblem" aria-hidden="true">${icon(({control:'trip',sheets:'file',fleet:'truck',trips:'trip',monthly:'file',reports:'report',settings:'settings',clients:'clients',finance:'finance'})[page]||'dashboard')}</span><div><div class="eyebrow">${({control:'PENDANAAN & VERIFIKASI RIT',sheets:'ACCOUNTING WORKSHEET',dashboard:'IKHTISAR MANAJEMEN',clients:'ANALISIS KLIEN & REVENUE',finance:'PENCATATAN KEUANGAN',fleet:'KINERJA DAN STATUS ARMADA',trips:'AKTIVITAS OPERASIONAL',reports:'EVALUASI OPERASIONAL MINGGUAN',monthly:'PELAPORAN MANAJEMEN',settings:'PENGELOLAAN DATA'})[page]}</div><h1>${names[page]}</h1><p class="sub">${({control:'Pemantauan uang jalan, surat jalan, dan penyelesaian kasbon per armada.',sheets:'Pencatatan dan pembaruan transaksi melalui worksheet per armada.',dashboard:'Ringkasan indikator keuangan dan operasional berdasarkan periode terpilih.',clients:'Analisis revenue dan kontribusi klien terhadap kinerja operasional armada.',finance:'Daftar transaksi revenue dan expenses berdasarkan periode, armada, dan klien.',fleet:'Informasi kinerja keuangan, status kendaraan, dan aktivitas layanan armada.',trips:'Pencatatan perjalanan, penugasan, dan status pengiriman armada.',reports:'Ringkasan aktivitas dan evaluasi operasional per periode mingguan.',monthly:'Laporan keuangan manajemen berdasarkan periode bulanan dan cakupan armada.',settings:'Pengelolaan sumber data, pencadangan, dan riwayat pembaruan.'})[page]}</p></div></div><div class="actions">${['sheets','fleet','trips'].includes(page)?`<button class="btn" data-page="control">${icon('trip')}Kontrol rit & kasbon ↗</button>`:''}${!['dashboard','monthly','settings','sheets','fleet','control'].includes(page)?`<button class="btn primary" data-action="${button[0]}">${icon('plus')}${button[1]}</button>`:''}</div></div>${({control:()=>control.html(),sheets:()=>sheetEditor.html(),dashboard,clients,finance,fleet,trips,reports,monthly,settings})[page]()}<footer class="footer no-print"><span>PT JAYA BINTANG TERANG</span><span>${page==='control'?'Kontrol bersama · Accounting di browser ini · ':status.storage==='browser'?'Data hanya di browser ini · ':' '}Pembaruan rutin oleh tim</span></footer></main></div><input type="file" id="import-file" accept=".json,application/json" hidden>`;if(page==='control')control.mount(document.getElementById('rit-control'));if(page==='trips')mapCleanup=mountOperationsMap(document.getElementById('operations-map'));if(page==='sheets')sheetEditor.mount(document.getElementById('sheet-editor'));if(focused)document.getElementById(focused)?.focus({preventScroll:true});}
function field(label,name,value='',o={}){const {kind='text',required=false,values=[],full=false,min='',max='',list=''}=o;return `<label class="field ${full?'full':''}"><span>${label}</span>${kind==='select'?`<select name="${name}" ${required?'required':''}>${options(values,value)}</select>`:kind==='textarea'?`<textarea name="${name}" maxlength="3000">${esc(value)}</textarea>`:`<input name="${name}" type="${name==='amount'?'text':kind}" ${name==='amount'?'inputmode="numeric" data-money-input':''} value="${esc(name==='amount'&&value!==''?Number(value).toLocaleString('id-ID'):value)}" ${required?'required':''} ${min!==''?`min="${min}"`:''} ${max!==''?`max="${max}"`:''} ${list?`list="${list}"`:''} ${kind==='number'?'step="1"':'maxlength="200"'}>`}</label>`;}
function openForm(kind,id=''){modal.classList.remove('detail-dialog');modal.setAttribute('aria-labelledby','form-title');delete modal.dataset.tone;formKind=kind;formId=id;let title='',fields='';const clientsList=`<datalist id="client-options">${allClients().map(c=>`<option value="${esc(c.name)}"></option>`).join('')}</datalist>`;
 if(kind==='tx'){const t=state.transactions.find(t=>t.id===id)||{date:today(),plate:truck==='all'?plates[0]:truck,type:'Pemasukan',category:incomeCategories[0],income:0,expense:0,rit:0,customer:client==='all'?'':cname(client),description:''};title=id?'Edit transaksi':'Tambah transaksi';fields=`<div class="transaction-guide full">${icon('finance')}<div><strong>Catat sesuai jenis transaksi.</strong><span>Kategori mengikuti revenue atau expenses. Hubungkan klien untuk memantau kontribusinya.</span></div></div>`+field('Jenis transaksi','type',t.type,{kind:'select',values:['Pemasukan','Pengeluaran']})+field('Kategori','category',categoryLabel(t.category),{kind:'select',values:categoriesFor(t.type)})+field('Tanggal transaksi','date',t.date||'',{kind:'date',required:!id})+field('Armada','plate',t.plate,{kind:'select',values:plates})+field('Nominal (Rp)','amount',t.type==='Pemasukan'?(t.income??''):(t.expense??''),{kind:'number',min:0,max:1e13,required:true})+field('Jumlah rit','rit',t.rit,{kind:'number',min:0,max:100000})+field(t.type==='Pemasukan'?'Klien *':'Klien terkait (opsional)','customer',clientName(t.customer),{required:t.type==='Pemasukan',list:'client-options'})+field('Keterangan','description',t.description,{required:true})+clientsList+`<p class="sub field full">${id&&!t.date?'Tanggal historis boleh tetap kosong; periode asal dipertahankan. ':''}Biaya tanpa klien terkait masuk biaya umum armada. Nominal 0 berbeda dari nominal yang belum diisi.</p>`;}
 if(kind==='client'){const master=state.clients.find(c=>c.id===id);const matched=allClients().find(c=>c.key===id);const c=master||{name:matched?.name||'',contact:'',notes:''};title=master||matched?'Profil klien':'Tambah klien';fields=field('Nama klien','name',clientName(c.name),{required:true,full:true})+field('Kontak / PIC (opsional)','contact',c.contact,{full:true})+field('Catatan klien','notes',c.notes,{kind:'textarea',full:true});}
 if(kind==='trip'){const t=state.trips.find(t=>t.id===id)||{date:today(),plate:truck==='all'?plates[0]:truck,customer:client==='all'?'':cname(client),driver:'',origin:'',destination:'',status:'Terjadwal'};title=id?'Perbarui trip':'Tambah trip';fields=field('Tanggal','date',t.date,{kind:'date',required:true})+field('Armada','plate',t.plate,{kind:'select',values:plates})+field('Klien','customer',clientName(t.customer),{required:true,list:'client-options'})+field('Driver','driver',t.driver,{required:true})+field('Asal','origin',t.origin,{required:true})+field('Tujuan','destination',t.destination,{required:true})+field('Status pengiriman','status',t.status,{kind:'select',values:['Terjadwal','Dalam perjalanan','Selesai','Dibatalkan'],full:true})+clientsList;}
 if(kind==='fleet'){const f=state.fleet.find(f=>f.plate===id);title='Perbarui '+f.plate;fields=field('Status kendaraan','status',f.status,{kind:'select',values:['Belum diperbarui','Siap jalan','Beroperasi','Servis','Idle']})+field('Servis berikutnya','serviceDue',f.serviceDue,{kind:'date'})+field('Masa berlaku dokumen','documentDue',f.documentDue,{kind:'date'});}
 if(kind==='report'){const r=state.reports.find(r=>r.id===id)||{week:today(),status:'Draft',notes:''};title=id?'Tinjau laporan mingguan':'Buat laporan mingguan';fields=field('Tanggal mulai (7 hari)','week',r.week,{kind:'date',required:true})+field('Status','status',r.status,{kind:'select',values:['Draft','Ditinjau']})+field('Catatan evaluasi','notes',r.notes,{kind:'textarea',full:true});}
 if(kind==='monthly'){const r=state.monthlyReports.find(r=>monthlyReportKey(r)===monthlyReportKey({month:reportMonth,plate:reportTruck}))||{preparedBy:'',status:'Draft',notes:''};title='Evaluasi '+monthLabel(reportMonth)+' · '+(reportTruck==='all'?'Semua truk':reportTruck);fields=field('Disusun oleh','preparedBy',r.preparedBy)+field('Status penelaahan','status',r.status,{kind:'select',values:['Draft','Ditinjau']})+field('Catatan evaluasi manajemen','notes',r.notes,{kind:'textarea',full:true})+'<p class="sub field full">Angka laporan dihitung dari transaksi terkini. Status Ditinjau menandai pemeriksaan, belum mengunci transaksi.</p>';}
 modal.innerHTML=`<form id="edit-form"><div class="modal-head"><h2 id="form-title">${esc(title)}</h2><button type="button" class="close" data-action="close" aria-label="Tutup">×</button></div><div class="form-body">${fields}</div><div class="form-error" role="alert"></div><div class="form-foot"><button type="button" class="btn" data-action="close">Batal</button><button class="btn primary" type="submit">${icon('check')}Simpan</button></div></form>`;modal.showModal();if(kind==='tx'){const isIncome=modal.querySelector('[name="type"]').value==='Pemasukan';const rit=modal.querySelector('[name="rit"]');rit.disabled=!isIncome;if(!isIncome)rit.value=0;}}
function download(name,text,mime){const url=URL.createObjectURL(new Blob([text],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(rs=scoped(),name='transaksi'){const headers=['Tanggal','Periode','Armada','Keterangan','Jenis','Kategori','Klien','Revenue','Expenses','Rit'];const cell=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';const data=rs.map(t=>[t.date,t.period,t.plate,t.description,financialLabel(t.type),financialLabel(categoryLabel(t.category)),clientName(t.customer),t.income,t.expense,t.rit]);download('jaya-bintang-terang-'+name+'-'+today()+'.csv','\uFEFF'+[headers,...data].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
app.addEventListener('keydown',e=>{if(e.target.closest('[data-rit-truck]')&&['Enter',' '].includes(e.key)){e.preventDefault();openRitDetails(e.target.closest('[data-rit-truck]').dataset.ritTruck);return;}if(e.target.matches('.donut-segment')&&['Enter',' '].includes(e.key)){e.preventDefault();selectDonutClient(e.target.dataset.donutClient);}});
app.addEventListener('click',async e=>{const rit=e.target.closest('[data-rit-truck]');if(rit){openRitDetails(rit.dataset.ritTruck);return;}const segment=e.target.closest('[data-donut-client]');if(segment){selectDonutClient(segment.dataset.donutClient);return;}const b=e.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-cost-category'))return openCostDetails(b.dataset.costCategory);if(b.dataset.chartMonth)return openChartDetails(b.dataset.chartMonth,b.dataset.chartSeries);if(b.dataset.page){page=b.dataset.page;search='';offset=0;render();window.scrollTo(0,0);return;}if(b.dataset.client){if(modal.open)modal.close();client=b.dataset.client;page='clients';search='';render();window.scrollTo(0,0);return;}if(b.dataset.truck){truck=b.dataset.truck;page='finance';offset=0;render();return;}if(b.dataset.edit)return openForm('tx',b.dataset.edit);if(b.dataset.fleet)return openForm('fleet',b.dataset.fleet);if(b.dataset.trip)return openForm('trip',b.dataset.trip);if(b.dataset.report)return openForm('report',b.dataset.report);if(b.dataset.profile)return openForm('client',state.clients.find(c=>clientKey(c.name)===b.dataset.profile)?.id||b.dataset.profile);switch(b.dataset.action){case'google-login':{b.disabled=true;try{const result=await api('google-login','POST',{});window.location.assign(result.url);}catch(err){$('#login-message').textContent=err.message;b.disabled=false;}break;}case'logout':await api('logout','POST',{});state=null;await boot();break;case'fleet-motion':fleetMotion=!fleetMotion;render();break;case'menu':openNavigation();break;case'close-menu':closeNavigation();break;case'add-tx':openForm('tx');break;case'add-client':openForm('client');break;case'add-trip':openForm('trip');break;case'add-report':openForm('report');break;case'edit-monthly':openForm('monthly');break;case'export':exportCSV();break;case'monthly-csv':exportCSV(selectRows(state,{month:reportMonth,plate:reportTruck}),'laporan-'+reportMonth+'-'+(reportTruck==='all'?'semua-truk':reportTruck.replaceAll(' ','-')));break;case'print':{const original=document.title;document.title='JBT-Laporan-'+reportMonth+'-'+(reportTruck==='all'?'Semua-Truk':reportTruck.replaceAll(' ','-'));window.addEventListener('afterprint',()=>{document.title=original;},{once:true});window.print();break;}case'backup':download('jaya-bintang-terang-backup-'+today()+'.json',JSON.stringify(state,null,2),'application/json');break;case'import':$('#import-file').click();break;case'review':page='finance';quality='review';offset=0;render();break;case'unassigned-client':page='finance';quality='client';offset=0;client='all';render();break;case'reset':month='all';truck='all';client='all';search='';quality='all';type='all';offset=0;render();break;case'prev':offset=Math.max(0,offset-25);render();break;case'next':offset+=25;render();break;case'reload':await boot();break;}}catch(err){toast(err.message);}});
app.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;offset=0;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
app.addEventListener('change',async e=>{switch(e.target.id){case'month-filter':month=e.target.value;offset=0;render();break;case'truck-filter':truck=e.target.value;offset=0;render();break;case'client-filter':client=e.target.value;offset=0;render();break;case'type-filter':type=e.target.value;offset=0;render();break;case'quality-filter':quality=e.target.value;offset=0;render();break;case'report-truck':if(e.target.value==='all'||plates.includes(e.target.value)){reportTruck=e.target.value;render();}break;case'report-month':if(/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)){reportMonth=e.target.value;render();}break;case'import-file':try{const file=e.target.files[0];if(!file)return;if(file.size>2500000)throw Error('File terlalu besar (maksimal 2,5 MB).');const incoming=normalize(JSON.parse(await file.text()));validate(incoming);const next=structuredClone(state);let added=0;for(const key of ['transactions','trips','reports','monthlyReports']){const ids=new Set(next[key].map(r=>r.id));for(const r of incoming[key]){if(!ids.has(r.id)){if(key==='monthlyReports'&&next[key].some(m=>monthlyReportKey(m)===monthlyReportKey(r)))continue;next[key].push(r);ids.add(r.id);added++;}}}const keys=new Set(next.clients.map(c=>clientKey(c.name)));for(const c of incoming.clients){if(!keys.has(clientKey(c.name))){next.clients.push(c);keys.add(clientKey(c.name));added++;}}if(!state.transactions.length&&!state.trips.length)next.fleet=incoming.fleet;if(!added)return toast('Semua catatan sudah ada. Tidak ada duplikasi.');await commit(next);reportMonth=defaultReportMonth(state);render();toast(added+' catatan berhasil diimpor.');}catch(err){toast(err.message);}break;}});
modal.addEventListener('close',()=>{modal.classList.remove('detail-dialog');delete modal.dataset.tone;modal.removeAttribute('aria-labelledby');});
modal.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action==='close'){modal.close();return;}if(b.dataset.client){modal.close();client=b.dataset.client;page='clients';search='';offset=0;render();window.scrollTo(0,0);return;}if(b.dataset.edit)openForm('tx',b.dataset.edit);});
modal.addEventListener('focusout',e=>{if(e.target.matches('[data-money-input]')){try{const value=parseMoney(e.target.value);if(value!==null)e.target.value=value.toLocaleString('id-ID');}catch{}}});
modal.addEventListener('change',e=>{if(formKind==='tx'&&e.target.name==='type'){const type=e.target.value;modal.querySelector('[name="category"]').innerHTML=options(categoriesFor(type),categoriesFor(type)[0]);const c=modal.querySelector('[name="customer"]');c.required=type==='Pemasukan';const rit=modal.querySelector('[name="rit"]');rit.disabled=type!=='Pemasukan';if(type!=='Pemasukan')rit.value=0;c.previousElementSibling.textContent=type==='Pemasukan'?'Klien *':'Klien terkait (opsional)';}});
modal.addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('[type="submit"]');button.disabled=true;try{const f=Object.fromEntries(new FormData(e.target)),next=structuredClone(state);const id=formId||crypto.randomUUID();
 if(formKind==='tx'){const amount=parseMoney(f.amount);if(amount===null)throw Error('Nominal wajib diisi.');const prev=next.transactions.find(t=>t.id===id);const date=f.date||null;if(!date&&!prev)throw Error('Tanggal wajib diisi.');const t={...prev,id,date,period:date?monthLabel(date.slice(0,7)):prev.period,plate:f.plate,type:f.type,category:f.category,description:f.description.trim(),customer:f.customer.trim().replace(/\s+/g,' '),rit:f.type==='Pemasukan'?Number(f.rit||0):0,income:f.type==='Pemasukan'?amount:0,expense:f.type==='Pengeluaran'?amount:0};if(!t.description)throw Error('Keterangan wajib diisi.');if(t.type==='Pemasukan'&&!t.customer)throw Error('Klien wajib diisi untuk revenue.');if(prev)next.transactions[next.transactions.indexOf(prev)]=t;else next.transactions.push(t);}
 if(formKind==='client'){const old=next.clients.find(c=>c.id===formId),derived=allClients().find(c=>c.key===formId);const name=f.name.trim().replace(/\s+/g,' ');const key=clientKey(name),oldKey=clientKey(old?.name||derived?.name);if(!key)throw Error('Nama klien wajib diisi.');if(next.clients.some(c=>c.id!==formId&&clientKey(c.name)===key))throw Error('Klien dengan nama ini sudah ada.');const c={id:old?.id||crypto.randomUUID(),name,contact:f.contact.trim(),notes:f.notes.trim()};if(old)next.clients[next.clients.indexOf(old)]=c;else next.clients.push(c);if(oldKey&&oldKey!==key){for(const t of [...next.transactions,...next.trips])if(clientKey(t.customer)===oldKey)t.customer=name;}client=key;}
 if(formKind==='trip'){const t={...f,id,customer:f.customer.trim()};const i=next.trips.findIndex(t=>t.id===id);if(i>=0)next.trips[i]=t;else next.trips.push(t);}
 if(formKind==='fleet'){const i=next.fleet.findIndex(t=>t.plate===formId);next.fleet[i]={...next.fleet[i],plate:formId,...f};}
 if(formKind==='report'){if(next.reports.some(r=>r.week===f.week&&r.id!==id))throw Error('Laporan untuk tanggal mulai ini sudah ada.');const t={...f,id};const i=next.reports.findIndex(r=>r.id===id);if(i>=0)next.reports[i]=t;else next.reports.push(t);}
 if(formKind==='monthly'){const i=next.monthlyReports.findIndex(r=>monthlyReportKey(r)===monthlyReportKey({month:reportMonth,plate:reportTruck}));const t={...f,id:i>=0?next.monthlyReports[i].id:crypto.randomUUID(),month:reportMonth,plate:reportTruck};if(i>=0)next.monthlyReports[i]=t;else next.monthlyReports.push(t);}
 await commit(next);modal.close();render();}catch(err){modal.querySelector('.form-error').textContent=err.message;}finally{button.disabled=false;}});
boot();
